import pytest


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay the given settings on the defaults mode=fast and level=3.

    keys[i] is set to values[i]. Returns the resulting values in the order
    mode, level, then any other keys in order of first appearance in `keys`.
    If a key repeats, the last value given for it wins, and its position
    is that of its first appearance. Raises ValueError if keys and values
    differ in length.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values differ in length")
    result: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=True):
        result[k] = v
    return list(result.values())


def test_defaults_only() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level() -> None:
    assert settings(["level"], ["9"]) == ["fast", "9"]


def test_override_both_any_order() -> None:
    assert settings(["level", "mode"], ["1", "safe"]) == ["safe", "1"]


def test_extra_keys_in_given_order() -> None:
    assert settings(["z", "a", "m"], ["1", "2", "3"]) == ["fast", "3", "1", "2", "3"]


def test_extras_mixed_with_known_keys() -> None:
    assert settings(["x", "mode", "y", "level"], ["1", "slow", "2", "7"]) == [
        "slow",
        "7",
        "1",
        "2",
    ]


def test_duplicate_last_wins_position_of_first() -> None:
    assert settings(["a", "b", "a"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_duplicate_known_key() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_empty_string_values() -> None:
    assert settings(["mode", "k"], ["", ""]) == ["", "3", ""]


def test_length_mismatch() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings([], ["1"])


def test_inputs_not_mutated() -> None:
    keys = ["a"]
    values = ["1"]
    settings(keys, values)
    assert keys == ["a"]
    assert values == ["1"]
